from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(prefix="/document-access", tags=["document-access-ui"])


@router.get("/ui", response_class=HTMLResponse)
async def document_access_ui():
    return HTMLResponse(DOCUMENT_ACCESS_HTML)


DOCUMENT_ACCESS_HTML = r"""
<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Материалы дела</title>
<style>
:root{--bg:#f3f5f8;--card:#fff;--ink:#172033;--muted:#667085;--line:#e4e7ec;--blue:#3157d5;--blue2:#eef2ff;--green:#137a4b;--green2:#ecfdf3;--red:#b42318;--red2:#fef3f2;--amber:#a15c00;--amber2:#fff7e6;--shadow:0 16px 42px rgba(16,24,40,.08)}
*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;background:var(--bg);margin:0;color:var(--ink)}a{color:inherit}.top{background:linear-gradient(135deg,#111827,#273653);color:#fff}.top-inner{max-width:1160px;margin:auto;padding:20px 22px;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:42px;height:42px;border-radius:13px;background:rgba(255,255,255,.13);display:grid;place-items:center;font-size:21px}.brand h1{font-size:21px;margin:0 0 3px}.brand p{margin:0;color:#d0d5dd;font-size:12px}.top-actions{display:flex;gap:8px;flex-wrap:wrap}.link{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:9px 12px;border-radius:10px;text-decoration:none;background:rgba(255,255,255,.1);font-weight:700;font-size:13px}.link:hover{background:rgba(255,255,255,.17)}main{max-width:1160px;margin:auto;padding:22px}.hero{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(260px,.5fr);gap:14px;margin-bottom:14px}.panel,.doc,.info{background:var(--card);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow)}.panel{padding:18px}.panel h2{margin:0 0 6px;font-size:20px}.muted{color:var(--muted);font-size:13px;line-height:1.5}.case-row{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:15px}input{border:1px solid #d0d5dd;background:#fff;border-radius:11px;padding:11px 12px;min-width:210px;font:inherit;color:var(--ink)}button{border:0;border-radius:11px;padding:10px 14px;min-height:40px;background:var(--blue);color:#fff;font-weight:760;cursor:pointer;font:inherit}button.secondary{background:#475467}button:disabled{opacity:.55;cursor:wait}.info{padding:17px;background:linear-gradient(145deg,#fff,var(--blue2));box-shadow:none}.info b{display:block;margin-bottom:7px}.security-list{display:grid;gap:8px;margin-top:11px}.security-item{display:flex;gap:8px;align-items:flex-start;font-size:12px;color:#475467}.dot{width:19px;height:19px;min-width:19px;border-radius:50%;display:grid;place-items:center;background:#d1fadf;color:var(--green);font-size:11px;font-weight:900}.context{display:flex;justify-content:space-between;align-items:center;gap:12px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:12px 14px;margin-bottom:12px}.context-main{display:flex;align-items:center;gap:10px;min-width:0}.case-badge,.role-badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:800}.case-badge{background:var(--blue2);color:var(--blue)}.role-badge{background:#f2f4f7;color:#475467}.feedback{min-height:24px;margin:8px 2px 12px;font-size:13px;line-height:1.45}.feedback.ok{color:var(--green)}.feedback.error{color:var(--red)}.feedback.warn{color:var(--amber)}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:0 0 12px}.metric{background:#fff;border:1px solid var(--line);border-radius:13px;padding:12px}.metric span{display:block;color:var(--muted);font-size:11px;margin-bottom:4px}.metric strong{font-size:18px}.docs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.doc{padding:16px;box-shadow:none;display:flex;flex-direction:column;gap:12px}.doc-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.doc h3{font-size:16px;margin:0 0 4px;line-height:1.3}.file{font-size:12px;color:#475467;overflow-wrap:anywhere}.badge{display:inline-flex;border-radius:999px;padding:5px 8px;background:var(--green2);color:var(--green);font-size:11px;font-weight:800;white-space:nowrap}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.cell{background:#f8fafc;border-radius:10px;padding:9px}.cell span{display:block;color:var(--muted);font-size:10px;margin-bottom:3px}.doc-actions{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-top:auto;padding-top:4px}.doc-actions .hint{font-size:11px;color:var(--muted);max-width:58%}.empty{background:#fff;border:1px dashed #d0d5dd;border-radius:16px;padding:34px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--ink);font-size:16px;margin-bottom:5px}.skeleton{background:#fff;border:1px solid var(--line);border-radius:15px;padding:20px;color:var(--muted);text-align:center}.hidden{display:none!important}
@media(max-width:850px){.hero{grid-template-columns:1fr}.docs{grid-template-columns:1fr}.top-inner{align-items:flex-start}.summary{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:580px){main{padding:12px}.top-inner{padding:16px 13px;flex-direction:column}.top-actions{width:100%}.link{flex:1}.case-row{align-items:stretch;flex-direction:column}.case-row input,.case-row button{width:100%}.context{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:1fr}.doc-actions{align-items:stretch;flex-direction:column}.doc-actions .hint{max-width:none}.doc-actions button{width:100%}.meta{grid-template-columns:1fr 1fr}}
</style>
</head>
<body>
<header class="top"><div class="top-inner"><div class="brand"><div class="brand-mark">🔐</div><div><h1>Материалы дела</h1><p>Защищённый просмотр и одноразовая выдача документов</p></div></div><div class="top-actions"><a id="messagesLink" class="link hidden" href="#">Переписка</a><a id="backLink" class="link" href="/operator">← Назад в кабинет</a></div></div></header>
<main>
<section class="hero">
  <div class="panel">
    <h2>Документы по обращению</h2>
    <div class="muted">Здесь показываются только файлы, которые прошли проверку безопасности и доступны вашей учётной записи. Для M2 доступ определяется текущим юристом консультации, для M1 — ответственным юристом дела.</div>
    <div id="caseRow" class="case-row"><input id="caseId" inputmode="numeric" autocomplete="off" placeholder="ID дела"><button id="loadButton" onclick="loadDocuments(this)">Открыть материалы</button></div>
  </div>
  <aside class="info"><b>Как защищена выдача</b><div class="muted">Файл не публикуется прямой ссылкой и не остаётся расшифрованным в хранилище.</div><div class="security-list"><div class="security-item"><span class="dot">✓</span><span>Разрешение привязано к текущей персональной сессии.</span></div><div class="security-item"><span class="dot">✓</span><span>Ссылка действует несколько минут и погашается после первого скачивания.</span></div><div class="security-item"><span class="dot">✓</span><span>Доступ к делу повторно проверяется непосредственно перед выдачей.</span></div></div></aside>
</section>
<div id="caseContext" class="context hidden"><div class="context-main"><span id="caseBadge" class="case-badge"></span><div><b id="caseTitle">Материалы обращения</b><div id="caseHint" class="muted">Доступ проверен текущей сессией</div></div></div><span id="roleBadge" class="role-badge"></span></div>
<div id="message" class="feedback" role="status" aria-live="polite"></div>
<div id="summary" class="summary hidden"></div>
<div id="content"></div>
</main>
<script>
let token='',loadingDocuments=false,sessionRoles=[];const pendingDocuments=new Set();
const $=id=>document.getElementById(id);
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function size(v){if(v===null||v===undefined)return '—';if(v<1024)return v+' Б';if(v<1048576)return (v/1024).toFixed(1)+' КБ';return (v/1048576).toFixed(1)+' МБ'}
function feedback(text,state=''){const el=$('message');el.className='feedback'+(state?' '+state:'');el.textContent=text}
function roleLabel(){if(sessionRoles.includes('lawyer'))return 'Юрист';if(sessionRoles.includes('superadmin'))return 'Суперадминистратор';if(sessionRoles.includes('admin'))return 'Администратор';return 'Сотрудник'}
function roleHome(){return sessionRoles.includes('lawyer')?'/lawyer/workspace/ui':'/admin/workdesk/ui'}
function currentCaseId(){const id=Number($('caseId').value);return Number.isInteger(id)&&id>0?id:0}
function applyContext(id){$('caseContext').classList.remove('hidden');$('caseBadge').textContent='Дело #'+id;$('roleBadge').textContent=roleLabel();$('backLink').href=roleHome();$('messagesLink').href='/message-center/ui?case_id='+id;$('messagesLink').classList.remove('hidden')}
function clearContext(){ $('caseContext').classList.add('hidden');$('summary').classList.add('hidden');$('summary').innerHTML='';$('messagesLink').classList.add('hidden') }
async function api(path,opts={}){const r=await fetch(path,{...opts,credentials:'same-origin',cache:'no-store',headers:{'x-admin-token':token,'Content-Type':'application/json',...(opts.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(d.detail||'Не удалось выполнить запрос');e.status=r.status;throw e}return d}
async function responseError(response,fallback){const data=await response.json().catch(()=>({}));const e=new Error(data.detail||fallback);e.status=response.status;return e}
function safeFileName(value,id){const name=String(value||('document-'+id)).replace(/[\\/:*?"<>|\r\n]/g,'_').trim();return name||('document-'+id)}
function documentCard(x){return `<article class="doc"><div class="doc-head"><div><h3>${esc(x.title||x.file_name||'Документ')}</h3><div class="file">${esc(x.file_name||'')}</div></div><span class="badge">✓ проверен</span></div><div class="meta"><div class="cell"><span>Тип</span><b>${esc(x.document_type||'—')}</b></div><div class="cell"><span>Размер</span><b>${esc(size(x.file_size))}</b></div><div class="cell"><span>Версия</span><b>${esc(x.version??'—')}</b></div><div class="cell"><span>Хранение</span><b>Зашифровано</b></div></div><div class="doc-actions"><div class="hint">Одноразовая защищённая выдача. Повторное скачивание создаёт новое разрешение.</div><button data-document-id="${Number(x.document_id)}" onclick="downloadDocument(${Number(x.document_id)},this)">Скачать документ</button></div></article>`}
function renderSummary(rows){const total=rows.length,totalBytes=rows.reduce((sum,x)=>sum+Number(x.file_size||0),0),versions=new Set(rows.map(x=>String(x.version??''))).size;$('summary').innerHTML=`<div class="metric"><span>Доступно документов</span><strong>${total}</strong></div><div class="metric"><span>Общий объём</span><strong>${esc(size(totalBytes))}</strong></div><div class="metric"><span>Версии файлов</span><strong>${versions||0}</strong></div>`;$('summary').classList.toggle('hidden',!rows.length)}
async function boot(){try{const r=await fetch('/auth/session',{credentials:'same-origin',cache:'no-store'});if(!r.ok){location.href='/login?next='+encodeURIComponent(location.pathname+location.search);return}const s=await r.json();sessionRoles=s.roles||[s.role];if(!sessionRoles.some(x=>['lawyer','admin','superadmin'].includes(x))){feedback('У вашей учётной записи нет доступа к материалам дел.','error');$('content').innerHTML='<div class="empty"><strong>Доступ ограничен</strong>Вернитесь в свой кабинет или обратитесь к администратору.</div>';$('caseRow').classList.add('hidden');return}token=s.api_token;$('backLink').href=roleHome();const preset=new URLSearchParams(location.search).get('case_id');if(preset){$('caseId').value=preset;$('caseRow').classList.add('hidden');await loadDocuments()}}catch(e){feedback('Не удалось проверить рабочую сессию. Обновите страницу или войдите снова.','error')}}
async function loadDocuments(button=null){if(loadingDocuments)return;const id=currentCaseId();if(!id){clearContext();feedback('Укажите корректный номер дела.','error');return}loadingDocuments=true;applyContext(id);const target=button||$('loadButton'),label=target?target.textContent:'';if(target){target.disabled=true;target.setAttribute('aria-busy','true');target.textContent='Загрузка…'}feedback('Проверяю доступ и загружаю материалы…');$('content').innerHTML='<div class="skeleton">Загрузка защищённых документов…</div>';try{const rows=await api('/document-access/cases/'+id+'/documents');renderSummary(rows);feedback(rows.length?`Доступ проверен. Найдено документов: ${rows.length}.`:'Доступ проверен. В деле пока нет доступных проверенных документов.',rows.length?'ok':'');$('content').innerHTML=rows.length?`<section class="docs">${rows.map(documentCard).join('')}</section>`:'<div class="empty"><strong>Проверенных документов пока нет</strong>Файлы появятся здесь после безопасной загрузки и проверки. Если документ должен быть доступен уже сейчас, откройте переписку по делу.</div>'}catch(e){renderSummary([]);if(e.status===401){feedback('Сессия завершилась. Перенаправляю на вход…','warn');setTimeout(()=>location.href='/login?next='+encodeURIComponent(location.pathname+location.search),400)}else if(e.status===403){feedback('У вас нет доступа к материалам этого дела. Ничего не было раскрыто.','error');$('content').innerHTML='<div class="empty"><strong>Доступ к делу не подтверждён</strong>Откройте дело из своей рабочей очереди или вернитесь в кабинет. Если ответственность по консультации только что изменилась, обновите очередь.</div>'}else{feedback(`Документы не загружены: ${e.message}`,'error');$('content').innerHTML='<div class="empty"><strong>Материалы временно не загружены</strong>Данные дела не изменены. Повторите загрузку или вернитесь в кабинет.</div>'}}finally{loadingDocuments=false;if(target){target.disabled=false;target.removeAttribute('aria-busy');target.textContent=label}}}
async function withDocumentGrant(id,button,work){if(pendingDocuments.has(id))return;pendingDocuments.add(id);const controls=Array.from(document.querySelectorAll(`[data-document-id="${id}"]`)),labels=new Map(controls.map(x=>[x,x.textContent]));controls.forEach(x=>{x.disabled=true;x.setAttribute('aria-busy','true')});if(button)button.textContent='Подготовка…';try{return await work()}finally{pendingDocuments.delete(id);controls.forEach(x=>{x.disabled=false;x.removeAttribute('aria-busy')});labels.forEach((label,x)=>{x.textContent=label})}}
async function downloadDocument(id,button){return withDocumentGrant(id,button,async()=>{feedback('Создаю одноразовое разрешение для текущей сессии…');try{const grant=await api('/document-access/documents/'+id+'/grant',{method:'POST',body:'{}'});feedback('Разрешение создано. Безопасно подготавливаю файл…');const response=await fetch(grant.download_url,{method:'GET',credentials:'same-origin',cache:'no-store',headers:{'x-admin-token':token}});if(!response.ok)throw await responseError(response,'Не удалось получить документ по одноразовому разрешению');const blob=await response.blob(),objectUrl=URL.createObjectURL(blob);try{const link=document.createElement('a');link.href=objectUrl;link.download=safeFileName(grant.file_name,id);document.body.appendChild(link);link.click();link.remove()}finally{setTimeout(()=>URL.revokeObjectURL(objectUrl),0)}feedback(`Документ «${safeFileName(grant.file_name,id)}» передан браузеру для сохранения.`,'ok')}catch(e){if(e.status===401)feedback('Сессия завершилась. Войдите снова и откройте дело из рабочей очереди.','error');else if(e.status===403)feedback('Доступ к этому документу больше не подтверждён. Файл не был выдан.','error');else feedback(`Документ не скачан: ${e.message}`,'error')}})}
boot();
</script>
</body>
</html>
"""